// Generated by Kargo: runs Kotlin/JS tests and reports them as TeamCity messages, which `kargo test` reads.
//
// The test module registers its suites and tests with kotlin-test when it loads. kotlin-test passes
// them to the adapter that `globalThis.kotlinTest.adapterTransformer` returns, so this file collects
// them first and runs them after the module loaded, one at a time, waiting for asynchronous tests.

const escape = (value) =>
  String(value).replace(/[|'\n\r[\]]/g, (c) => ({ '|': '||', "'": "|'", '\n': '|n', '\r': '|r', '[': '|[', ']': '|]' })[c]);

const show = (error) => (error instanceof Error ? String(error.stack || error) : String(error));

// Loads the tests with `load` and runs those whose `package.Class.test` name contains `filter`.
// `write` prints one line. Returns how many tests failed.
export async function run(load, { filter = '', write = (line) => console.log(line) } = {}) {
  const root = { children: [] };
  let current = root;
  globalThis.kotlinTest = {
    adapterTransformer: () => ({
      suite(name, ignored, body) {
        const suite = { name, ignored, children: [] };
        current.children.push(suite);
        const parent = current;
        current = suite;
        try {
          body();
        } finally {
          current = parent;
        }
      },
      test(name, ignored, body) {
        current.children.push({ name, ignored, body });
      },
    }),
  };
  await load();

  const message = (name, attributes) =>
    write(`##teamcity[${name}${Object.entries(attributes).map(([key, value]) => ` ${key}='${escape(value)}'`).join('')}]`);
  const selected = (node, path) =>
    node.children ? node.children.some((child) => selected(child, [...path, child.name])) : path.join('.').includes(filter);
  let failed = 0;
  const visit = async (node, path, ignored) => {
    for (const child of node.children) {
      const names = [...path, child.name];
      if (!selected(child, names)) continue;
      const skip = ignored || child.ignored;
      if (child.children) {
        message('testSuiteStarted', { name: child.name });
        await visit(child, names, skip);
        message('testSuiteFinished', { name: child.name });
      } else if (skip) {
        message('testIgnored', { name: child.name });
      } else {
        message('testStarted', { name: child.name });
        const started = Date.now();
        try {
          await child.body();
        } catch (error) {
          failed++;
          message('testFailed', { name: child.name, message: error?.message ?? String(error), details: show(error) });
        }
        message('testFinished', { name: child.name, duration: Date.now() - started });
      }
    }
  };
  await visit(root, [], false);
  return failed;
}
